  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Pearl Harbor and America Enters the War$j$, $j${"readings": [{"title": "Nehemiah 4 (King James Version)", "url": "/portal/bible/Nehemiah/4"}], "body": "On the morning of December 7, 1941, Japanese planes attacked the American naval base at Pearl Harbor, Hawaii. More than 2,400 Americans died and many ships were damaged. The next day President Roosevelt called it a date which will live in infamy, and Congress declared war on Japan. Germany and Italy then declared war on the United States.\n\nThe nation had to turn at once to war production. Factories that made cars made tanks and planes. The War Production Board directed industry, and the draft brought millions of men into service. Roosevelt and Churchill agreed on a Europe First strategy, since Germany was the greater danger.\n\nEarly in the Pacific war Japan won many victories, taking the Philippines, where American and Filipino troops suffered on the Bataan Death March. Then the tide began to turn. In April 1942 the Doolittle Raid struck Tokyo. At the Battle of Midway in June 1942, American forces sank four Japanese carriers, a turning point in the Pacific.\n\nIn the Atlantic, German submarines threatened shipping, and convoys and new technology reduced the danger.\n\nNehemiah 4:14 says, Be not ye afraid of them: remember the Lord, which is great and terrible, and fight for your brethren, your sons, and your daughters, your wives, and your houses.\n\nYour task: (1) Tell what happened at Pearl Harbor and how America responded. (2) Explain Europe First. (3) Tell why Midway was a turning point.\n\nFlorida standards: SS.912.A.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.6", "script": "Welcome to Unit 5. Listen, on the morning of December seventh, nineteen forty one, Japanese planes attacked the American naval base at Pearl Harbor, Hawaii. More than two thousand four hundred Americans died and many ships were damaged. The next day President Roosevelt called it a date which will live in infamy, and Congress declared war on Japan. Germany and Italy then declared war on the United States.\n\nNow watch this. The nation turned at once to war production. Factories that made cars made tanks and planes. The War Production Board directed industry, and the draft brought millions of men into service. Roosevelt and Churchill agreed on a Europe First strategy, since Germany was the greater danger.\n\nLook at this. Early in the Pacific war Japan won many victories, taking the Philippines, where American and Filipino troops suffered on the Bataan Death March. Then the tide began to turn. In April nineteen forty two the Doolittle Raid struck Tokyo. At the Battle of Midway in June nineteen forty two, American forces sank four Japanese carriers, a turning point in the Pacific.\n\nNehemiah four and fourteen says, Be not ye afraid of them: remember the Lord, which is great and terrible, and fight for your brethren, your sons, and your daughters, your wives, and your houses.\n\nYour task today. Tell what happened at Pearl Harbor and how America responded. Explain Europe First. And tell why Midway was a turning point. Take the four question check.\n\nCourage rests on faith. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Pearl Harbor and America Enters the War$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 The War in Europe and the Pacific$j$, $j${"readings": [{"title": "Psalm 144 (King James Version)", "url": "/portal/bible/Psalms/144"}], "body": "In Europe the Allies, the United States, Britain and the Soviet Union, fought the Axis. The Soviets stopped Germany at Stalingrad, a turning point on the Eastern Front. American and British forces landed in North Africa in 1942 and then invaded Italy in 1943.\n\nOn June 6, 1944, called D Day, the Allies landed on the beaches of Normandy, France, in the largest sea invasion in history under General Dwight Eisenhower. They freed Paris in August. In December 1944 Germany attacked in the Battle of the Bulge but was beaten. Germany surrendered on May 8, 1945, called V E Day, after Hitler's death.\n\nIn the Pacific, American forces used island hopping, skipping strong Japanese bases and taking key islands. Admiral Chester Nimitz and General Douglas MacArthur led the campaign. Battles at Guadalcanal, Iwo Jima and Okinawa were fierce. Navajo code talkers sent secret messages in their own language that Japan could not break.\n\nPsalm 144:1 says, Blessed be the LORD my strength which teacheth my hands to war, and my fingers to fight.\n\nYour task: (1) Explain what D Day was. (2) Define island hopping. (3) Tell how the code talkers helped.\n\nFlorida standards: SS.912.A.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.6", "script": "Welcome back. Listen, in Europe the Allies, the United States, Britain and the Soviet Union, fought the Axis. The Soviets stopped Germany at Stalingrad, a turning point on the Eastern Front. American and British forces landed in North Africa in nineteen forty two and invaded Italy in nineteen forty three.\n\nNow watch this. On June sixth, nineteen forty four, called D Day, the Allies landed on the beaches of Normandy, France, in the largest sea invasion in history under General Dwight Eisenhower. They freed Paris in August. In December nineteen forty four Germany attacked in the Battle of the Bulge but was beaten. Germany surrendered on May eighth, nineteen forty five, called V E Day.\n\nLook at this. In the Pacific, American forces used island hopping, skipping strong Japanese bases and taking key islands. Admiral Chester Nimitz and General Douglas MacArthur led the campaign. Battles at Guadalcanal, Iwo Jima and Okinawa were fierce. Navajo code talkers sent secret messages in their own language that Japan could not break.\n\nPsalm one hundred forty four and one says, Blessed be the LORD my strength which teacheth my hands to war, and my fingers to fight.\n\nYour task today. Explain what D Day was. Define island hopping. And tell how the code talkers helped. Take the four question check.\n\nHonor every sacrifice. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 The War in Europe and the Pacific$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 The Home Front, Internment and Double V$j$, $j${"readings": [{"title": "Deuteronomy 16 (King James Version)", "url": "/portal/bible/Deuteronomy/16"}], "body": "The war changed life at home. Factories hired millions of new workers. Women took jobs in shipyards and plants, shown in the image of Rosie the Riveter. Families used ration books for sugar, meat and gas, planted victory gardens and bought war bonds. Unemployment ended and the Depression was over.\n\nNot all Americans were treated fairly. After Pearl Harbor, Executive Order 9066 forced about 120,000 people of Japanese ancestry, most of them American citizens, from their homes on the West Coast into internment camps. The Supreme Court upheld this in Korematsu v. United States in 1944. Congress later apologized and paid reparations in 1988. This was a grave injustice. Yet Japanese American soldiers of the 442nd Regimental Combat Team were among the most decorated units.\n\nAfrican Americans served in segregated units. They pursued a Double V campaign, victory over enemies abroad and victory over racism at home. The Tuskegee Airmen, Black pilots trained in Alabama, escorted bombers with great skill. In 1941 A. Philip Randolph pressed Roosevelt to ban discrimination in defense plants. Hispanic Americans, Native Americans and women also served.\n\nDeuteronomy 16:20 says, That which is altogether just shalt thou follow, that thou mayest live, and inherit the land which the LORD thy God giveth thee.\n\nYour task: (1) Describe three ways Americans supported the war at home. (2) Explain Executive Order 9066 and why it was unjust. (3) Explain the Double V campaign.\n\nFlorida standards: SS.912.A.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.6", "script": "Welcome back. Listen, the war changed life at home. Factories hired millions of new workers. Women took jobs in shipyards and plants, shown in the image of Rosie the Riveter. Families used ration books for sugar, meat and gas, planted victory gardens and bought war bonds. Unemployment ended and the Depression was over.\n\nNow watch this. Not all Americans were treated fairly. After Pearl Harbor, Executive Order ninety sixty six forced about one hundred twenty thousand people of Japanese ancestry, most of them American citizens, from their homes on the West Coast into internment camps. The Supreme Court upheld this in Korematsu v. United States in nineteen forty four. Congress later apologized and paid reparations in nineteen eighty eight. This was a grave injustice. Yet Japanese American soldiers of the four hundred forty second Regimental Combat Team were among the most decorated units.\n\nLook at this. African Americans served in segregated units. They pursued a Double V campaign, victory over enemies abroad and victory over racism at home. The Tuskegee Airmen, Black pilots trained in Alabama, escorted bombers with great skill. In nineteen forty one A. Philip Randolph pressed Roosevelt to ban discrimination in defense plants.\n\nDeuteronomy sixteen and twenty says, That which is altogether just shalt thou follow, that thou mayest live, and inherit the land which the LORD thy God giveth thee.\n\nYour task today. Describe three ways Americans supported the war at home. Explain Executive Order ninety sixty six and why it was unjust. And explain the Double V campaign. Take the four question check.\n\nJustice must guide us even in fear. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 The Home Front, Internment and Double V$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 The Holocaust, the Atomic Bomb and a New World Order$j$, $j${"readings": [{"title": "Isaiah 2 (King James Version)", "url": "/portal/bible/Isaiah/2"}], "body": "The Nazis carried out the Holocaust, the murder of about six million Jews and millions of others, including Roma, disabled people and political prisoners, in ghettos, camps and killing centers such as Auschwitz. Christians like Corrie ten Boom and Dietrich Bonhoeffer risked their lives to resist and to hide the persecuted. When Allied soldiers liberated the camps in 1945, the world saw the evil. The Nuremberg Trials held Nazi leaders accountable.\n\nFighting in the Pacific continued. President Harry Truman, after Roosevelt's death in April 1945, faced a hard choice. To end the war without a costly invasion of Japan, he approved the use of the atomic bomb. Bombs fell on Hiroshima on August 6 and Nagasaki on August 9, 1945. Japan surrendered on August 15, with the formal surrender on September 2, V J Day. Historians still debate the decision, weighing lives saved against the suffering caused.\n\nThe world tried to build peace. The United Nations was formed in 1945. The GI Bill helped veterans attend college and buy homes. The war left the United States and the Soviet Union as the two superpowers.\n\nIsaiah 2:4 says, And he shall judge among the nations, and shall rebuke many people: and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up sword against nation, neither shall they learn war any more.\n\nYour task: (1) Explain the Holocaust and how some Christians responded. (2) Describe the debate over the atomic bomb. (3) Name two postwar results.\n\nFlorida standards: SS.912.A.6.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.A.6", "script": "Welcome back. Listen, the Nazis carried out the Holocaust, the murder of about six million Jews and millions of others, including Roma, disabled people and political prisoners, in ghettos, camps and killing centers such as Auschwitz. Christians like Corrie ten Boom and Dietrich Bonhoeffer risked their lives to resist and to hide the persecuted. When Allied soldiers liberated the camps in nineteen forty five, the world saw the evil. The Nuremberg Trials held Nazi leaders accountable.\n\nNow watch this. Fighting in the Pacific continued. President Harry Truman, after Roosevelt's death in April nineteen forty five, faced a hard choice. To end the war without a costly invasion of Japan, he approved the use of the atomic bomb. Bombs fell on Hiroshima on August sixth and Nagasaki on August ninth. Japan surrendered on August fifteenth, with the formal surrender on September second. Historians still debate the decision, weighing lives saved against the suffering caused.\n\nLook at this. The world tried to build peace. The United Nations was formed in nineteen forty five. The GI Bill helped veterans attend college and buy homes. The war left the United States and the Soviet Union as the two superpowers.\n\nIsaiah two and four says, And he shall judge among the nations, and shall rebuke many people: and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up sword against nation, neither shall they learn war any more.\n\nYour task today. Explain the Holocaust and how some Christians responded. Describe the debate over the atomic bomb. And name two postwar results. Take the four question check.\n\nPray for peace and defend the helpless. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 The Holocaust, the Atomic Bomb and a New World Order$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: America in World War II$j$, $j${"prompt": "Write an essay answering this question: How did World War II change the United States and the world? Use complete sentences and label each part. Isaiah 2:4 says, And he shall judge among the nations, and shall rebuke many people: and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up sword against nation, neither shall they learn war any more.\n\nPart 1: Explain how the war began for America and describe two key battles in the Pacific.\nPart 2: Explain D Day and why it mattered in Europe.\nPart 3: Describe how war production, women and minorities changed the home front.\nPart 4: Explain internment, why it was wrong, and how it was later addressed.\nPart 5: Explain the Holocaust and the debate over the atomic bomb.\nPart 6: Give your thesis on the most important result of the war, using evidence and one KJV verse.", "rubric": "70 points. Entry into the war and Pacific battles: 10 points. D Day and Europe: 8 points. Home front: 10 points. Internment: 10 points. Holocaust and atomic bomb: 12 points. Thesis and evidence: 16 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: America in World War II$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Courage, Conscience and Justice$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains why Americans fought in World War II, (2) tells how Christians like Corrie ten Boom and Dietrich Bonhoeffer lived out faith in a time of evil, (3) describes what the internment of Japanese Americans teaches us about protecting rights in a crisis, and (4) connects your answer to Deuteronomy 16:20, which says, That which is altogether just shalt thou follow, that thou mayest live, and inherit the land which the LORD thy God giveth thee. Then write a respectful reply of at least 40 words to another student, or answer this question: Why was the Battle of Midway so important? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Courage, Conscience and Justice$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Pearl Harbor and America Enters the War$j$, $j${"questions": [{"q": "Pearl Harbor was attacked on:", "options": ["June 6, 1944", "December 7, 1941", "November 11, 1918", "April 12, 1861"]}, {"q": "The Europe First strategy meant:", "options": ["Defeat Japan before Germany", "Avoid Europe", "Defeat Germany before Japan", "Join the League of Nations"]}, {"q": "The Battle of Midway was a turning point in the:", "options": ["Mediterranean", "Pacific", "Atlantic", "Arctic"]}, {"q": "The Bataan Death March took place in the:", "options": ["Philippines", "Hawaii", "Germany", "Alaska"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Pearl Harbor and America Enters the War$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,1,0}'::int[], array[$j$Japan struck the naval base in Hawaii.$j$,$j$Germany was seen as the greater threat.$j$,$j$Four Japanese carriers were sunk.$j$,$j$American and Filipino prisoners suffered terribly.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Pearl Harbor and America Enters the War$j$ on conflict (item_id) do nothing;
