  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,0}'::int[], array[$j$It took place on June 6, 1944.$j$,$j$Eisenhower led the invasion.$j$,$j$It saved lives and moved the Navy toward Japan.$j$,$j$Japan never broke their code.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: The War in Europe and the Pacific$j$ on conflict (item_id) do nothing;
