  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,0,3}'::int[], array[$j$About 120,000 people were forced into camps.$j$,$j$They escorted bombers with a strong record.$j$,$j$Millions of women took factory jobs.$j$,$j$It saved supplies for the military.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: The Home Front, Internment and Double V$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: The Holocaust, the Atomic Bomb and a New World Order$j$, $j${"questions": [{"q": "About how many Jews were murdered in the Holocaust?", "options": ["Six thousand", "Six hundred", "Six million", "Sixty thousand"]}, {"q": "The atomic bombs were dropped on:", "options": ["Tokyo and Osaka", "Berlin and Munich", "Hiroshima and Nagasaki", "Pearl Harbor and Midway"]}, {"q": "The GI Bill helped veterans by:", "options": ["Ending rationing", "Paying for college and home loans", "Drafting them", "Giving them land in the West"]}, {"q": "The United Nations was formed in:", "options": ["1919", "1865", "1776", "1945"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: The Holocaust, the Atomic Bomb and a New World Order$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,3}'::int[], array[$j$Millions of others were also killed.$j$,$j$This was in August 1945.$j$,$j$It reshaped postwar America.$j$,$j$It aimed to keep peace among nations.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: The Holocaust, the Atomic Bomb and a New World Order$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: World War II$j$, $j${"questions": [{"q": "President during most of World War II was:", "options": ["Franklin D. Roosevelt", "Herbert Hoover", "Woodrow Wilson", "Harry Truman"]}, {"q": "Germany surrendered on:", "options": ["December 7, 1941", "June 6, 1944", "May 8, 1945", "August 6, 1945"]}, {"q": "The Battle of Stalingrad was won by the:", "options": ["Italy", "Japan", "Soviet Union", "United States"]}, {"q": "The Double V campaign sought victory over:", "options": ["Germany and Italy", "Enemies abroad and racism at home", "Spain and Cuba", "Drought and flood"]}, {"q": "Which court case upheld internment?", "options": ["Brown v. Board of Education", "Korematsu v. United States", "Marbury v. Madison", "Plessy v. Ferguson"]}, {"q": "Who succeeded Roosevelt as president?", "options": ["John Kennedy", "Herbert Hoover", "Harry Truman", "Dwight Eisenhower"]}, {"q": "The Nuremberg Trials judged:", "options": ["Japanese soldiers", "Soviet farmers", "Nazi leaders", "American generals"]}, {"q": "The two superpowers after the war were:", "options": ["Germany and Japan", "Italy and Spain", "Britain and France", "The United States and the Soviet Union"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: World War II$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,1,1,2,2,3}'::int[], array[$j$He died in April 1945.$j$,$j$That day is called V E Day.$j$,$j$It stopped Germany on the Eastern Front.$j$,$j$African Americans fought for democracy abroad and at home.$j$,$j$Congress later apologized.$j$,$j$He faced the atomic bomb decision.$j$,$j$They held leaders accountable for crimes.$j$,$j$Their rivalry began the Cold War.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: World War II$j$ on conflict (item_id) do nothing;
